import sys
# All names starting with 'WT_STAT_DSRC_' are renamed to
# the wiredtiger.stat.dsrc class, those starting with 'WT_STAT_CONN' are
# renamed to the wiredtiger.stat.conn class. All names starting with 'WT_STAT_SESSION'
# are renamed to the wiredtiger.stat.session class.
def _rename_with_prefix(prefix, toclass):
    curmodule = sys.modules[__name__]
    for name in dir(curmodule):
        if name.startswith(prefix):
            shortname = name[len(prefix):].lower()
            setattr(toclass, shortname, getattr(curmodule, name))
            delattr(curmodule, name)

_rename_with_prefix('WT_STAT_CONN_', stat.conn)
_rename_with_prefix('WT_STAT_DSRC_', stat.dsrc)
_rename_with_prefix('WT_STAT_SESSION_', stat.session)
_rename_with_prefix('WT_FS_', FileSystem)
_rename_with_prefix('WT_FILE_HANDLE_', FileHandle)
del _rename_with_prefix

def _page_log_complete_checkpoint_args_get_metadata(self):
    return getattr(self, '_checkpoint_metadata_python_value', None)

def _page_log_complete_checkpoint_args_set_metadata(self, value):
    if value is None:
        self._clear_checkpoint_metadata()
        self._checkpoint_metadata_python_value = None
        return
    ret = self._set_checkpoint_metadata(value)
    if ret != 0:
        raise WiredTigerError(wiredtiger_strerror(ret))
    self._checkpoint_metadata_python_value = value

PageLogCompleteCheckpointArgs.checkpoint_metadata = property(
    _page_log_complete_checkpoint_args_get_metadata,
    _page_log_complete_checkpoint_args_set_metadata)

del _page_log_complete_checkpoint_args_get_metadata
del _page_log_complete_checkpoint_args_set_metadata

def _crypt_keys_get_keys(self):
    return getattr(self, '_keys_python_value', None)

def _crypt_keys_set_keys(self, value):
    if value is None:
        self._clear_keys()
        self._keys_python_value = None
        return
    ret = self._set_keys(value)
    if ret != 0:
        raise WiredTigerError(wiredtiger_strerror(ret))
    self._keys_python_value = value

CryptKeys.keys = property(_crypt_keys_get_keys, _crypt_keys_set_keys)

del _crypt_keys_get_keys
del _crypt_keys_set_keys


